"""First-run setup: default file locations and a safe starter policy."""

import json
import os
from pathlib import Path

from repoward.policy.loader import parse_policy

HOME_ENV = "REPOWARD_HOME"
POLICY_FILE = "policy.yaml"
AUDIT_FILE = "audit.jsonl"
APPROVALS_FILE = "approvals.db"
FLOW_FILE = "flow.db"
STARTER_ROLES = ("reader", "contributor")

_STARTER_POLICY = """\
# Generated by repoward init. Check changes with: repoward validate-policy <this file>
version: 1
default: deny

repos:
  allow: {repos}

paths:
  deny:
    - ".github/**"
    - "**/.git/**"
    - "**/.env*"
    - "**/secrets/**"
    - "**/*.pem"
    - "**/id_rsa*"
    - ".gitmodules"

# 'pat' reads GITHUB_TOKEN. 'app' issues a narrow token per call, and also needs client_id,
# installation_id, and GITHUB_APP_PRIVATE_KEY_FILE in the environment.
github_auth:
  mode: pat

branches:
  write_prefix: "agent/"

pull_requests:
  allow_non_draft: false

# Merging stays off until you turn it on here and give a role the tool.
dangerous_tools:
  github_merge_pull_request: {{ enabled: false }}
  github_delete_branch: {{ enabled: true }}

approvals:
  ttl_minutes: 15
  max_pending_per_principal: 20
  # Let a real pull request review approve a merge. Needs a bot or GitHub App identity.
  github_review: {{ enabled: false, min_permission: write }}

flow_guard:
  enabled: true
  window_minutes: 60
  on_private_to_public: deny
  on_untrusted_author: require_approval
  trusted_associations: [OWNER, MEMBER, COLLABORATOR]
  single_repo: false

roles:
  reader:
    tools:
      - ping
      - github_list_issues
      - github_get_issue
      - github_search_code
      - github_get_file
      - ci_get_status
      - ci_get_job_logs
  contributor:
    inherits: reader
    tools:
      - github_create_branch
      - github_commit_files
      - github_create_pull_request
      - github_comment
    commit_limits: {{ max_files: 20, max_bytes: 200000 }}
  maintainer:
    inherits: contributor
    tools: [github_delete_branch, github_merge_pull_request]
    require_approval: [github_delete_branch, github_merge_pull_request]

rate_limits:
  default: {{ per_minute: 30 }}
  github_commit_files: {{ per_minute: 5 }}
  github_search_code: {{ per_minute: 8 }}

# The role this server's single local user gets. Change it here, not in client config.
stdio:
  role: {role}
"""


def default_dir() -> Path:
    """Where repoward keeps its files. Set REPOWARD_HOME to move them."""
    configured = os.environ.get(HOME_ENV)
    return Path(configured) if configured else Path.home() / ".repoward"


def starter_policy(repos: list[str], role: str) -> str:
    """Render a starter policy, proving it loads before anyone relies on it."""
    text = _STARTER_POLICY.format(repos=json.dumps(repos), role=role)
    parse_policy(text.encode("utf-8"))
    return text


def write_starter(directory: Path, repos: list[str], role: str) -> Path:
    """Write the starter policy. An existing policy is never overwritten."""
    text = starter_policy(repos, role)
    directory.mkdir(parents=True, exist_ok=True)
    path = directory / POLICY_FILE
    with path.open("x", encoding="utf-8") as handle:
        handle.write(text)
    return path


def client_config(directory: Path) -> str:
    """The MCP client entry to paste. The token stays a placeholder on purpose."""
    args = ["repoward", "serve", "--dir", str(directory.resolve())]
    entry = {"command": "uvx", "args": args, "env": {"GITHUB_TOKEN": "<your-token>"}}
    return json.dumps({"mcpServers": {"repoward": entry}}, indent=2)
